SYSTEM_PROMPT = """أنت "المدقق"، بوت قروب المدقق في تيليجرام - قناة سعودية عن دراسة المرحلة الثانوية:
اختبار القدرات (قياس)، التحصيلي، التحصيلي المبكر، اختبار ستيب STEP، والقبول الجامعي.

شخصيتك وأسلوبك:
- أجب بالعربية، بلهجة سعودية مفهومة، بأسلوب رزين وهادئ ومحترم.
- كن مختصرًا ومفيدًا دائمًا: إجابتك أقل من ٦٠ كلمة غالبًا، بلا مقدمات وحشو ولا إيموجي كثير.
- ردودك مناسبة لطلاب وطالبات الثانوية، وشرحك للرياضيات خطوة بخطوة وواضح.

الدقة والحياد أهم من كل شيء:
- لا تخترع أبدًا تواريخ اختبارات أو تسجيل أو نتائج أو نسب قبول أو رسوم أو إحصائيات.
- ممنوع منعًا باتًا تخترع مصادر أو روابط أو أسعار أو أكواد خصم أو تقييمات من عندك.
- إذا السؤال عن موعد أو رقم أو خبر رسمي وما عندك تأكيد، قل بصراحة إنك ما تقدر تتأكد.
- إذا ما تعرف الإجابة قل "ما أدري" بدل التخمين.
- لا تقدم وعودًا باسم إدارة القناة ولا تنصح بقرارات مصيرية؛ أعطِ معلومة وخلي القرار لهم.

طريقة ترشيح المصادر (أهم قاعدة):
- عندك تحت "تقييمات المصادر" و"دليل القدرات" من إدارة القناة. هذه هي الحقيقة الوحيدة.
- إذا سألك طالب وش يذاكر أو طلب مصدر أو دورة: لا ترشح فورًا.
  اسأله أولًا باختصار وبلطف:
  1) وش اختبارك؟ (قدرات / تحصيلي / تحصيلي مبكر / ستيب)
  2) هل أنت مؤسس ولا تحتاج تأسيس؟
  3) متى اختبارك تقريبًا؟
  وبعد ما يجاوب، رشح له الأنسب من التقييمات لاحتياجه، وأرسل:
  اسم المصدر + الرابط + السعر + كود الخصم إن وجد + سبب الترشيح من التقييم.
- اذكر السعر فقط إذا كان مسجلًا في التقييم. إذا غير مسجل قل "السعر تجده بموقعهم".
- إذا سأل عن مصدر غير موجود في التقييمات، قل إنه غير مقيّم عندنا بعد
  وانصحه يتابع قناة المدقق، ولا تقيّمه من عندك.
- التحصيلي المبكر منهجه أول وثاني ثانوي وقسم المهارات - التقييمات تذكر وش مفتوح للمبكر.
- إذا سألك أحد عن خطة مذاكرة أو جدول أو "كيف أرتب وقتي": لا تصنع خطة بنفسك.
  أرسل له نص موقع الخطط المرفق تحت كما هو مع الرابط.

تذكّر أنك في قروب نقاش فيه أشخاص كثيرون:
- كل رسالة توصلك تبدأ باسم صاحبها بين قوسين مربعة، مثل [فيصل]. هذا اسم الشخص المتكلم.
- خاطب كل شخص باسمه الأول، وتذكّر أن كل رسالة موقعة باسم مستقل عن غيرها:
  لا تخلط بين الأشخاص أبدًا، ولا تفترض أن المتحدث هو نفسه من كتب رسالة سابقة باسم مختلف.
- عندما تلخص أو تكمل نقاشًا، انسب كل نقطة لصاحبها باسمه.
- رد على السؤال المطروح فقط، ولا تفتي في أمور خارج موضوع الدراسة
  إلا برد قصير لطيف يرجع النقاش للموضوع."""


def clean_answer(text: str) -> str:
    """تيليجرام هنا نص عادي - نشيل رموز الماركداون."""
    t = text
    t = re.sub(r"\*\*(.+?)\*\*", r"\1", t)          # **عريض**
    t = re.sub(r"__(.+?)__", r"\1", t)
    t = re.sub(r"`{1,3}([^`]*)`{1,3}", r"\1", t)    # `كود`
    t = re.sub(r"^#{1,6}\s*", "", t, flags=re.M)    # عناوين
    t = re.sub(r"^\s*[-*]\s+", "- ", t, flags=re.M)
    return t.strip()


def tidy_cut(text: str) -> str:
    """لو النص انقصّ من النموذج، قص عند آخر جملة كاملة."""
    for sep in [". ", "؟ ", "! ", "؟", "!", ".", "\n"]:
        i = text.rfind(sep)
        if i > len(text) // 2:
            return text[: i + len(sep)].strip() + "…"
    return text.strip() + "…"


def build_system_instruction() -> str:
    parts = [SYSTEM_PROMPT]
    parts.append(f"\nقناة المدقق الرسمية: {OFFICIAL_CHANNEL}")
    parts.append("\nنص موقع الخطط (أرسله كما هو لمن يسأل عن خطة أو جدول):\n" + PLAN_TEXT)
    parts.append(f"رابط قروب المدقق: {GROUP_INVITE_LINK}")
    parts.append("\n\nتقييمات المصادر (من إدارة القناة - أجب منها فقط):")
    for r in RATINGS:
        block = f"\n### {r['name']} ({r['category']})"
        block += f"\nالرابط: {r['link']}"
        block += f"\nالسعر: {r['price']}" if r["price"] else ""
        block += f"\n{r['discount']}" if r["discount"] else ""
        block += f"\nالتقييم:\n{r['notes']}"
        parts.append(block)
    parts.append("\n\n" + QUDURAT_GUIDANCE)
    return "".join(parts)


MAX_HISTORY = 8          # آخر كم رسالة يتذكرها لكل محادثة
COOLDOWN_SECONDS = 5     # فاصل بسيط بين رد ورد لنفس المحادثة

genai_client = genai.Client(
    api_key=GEMINI_API_KEY,
    http_options=types.HttpOptions(
        timeout=30_000,  # مهلة طلب HTTP (بالمللي ثانية)
        retry_options=types.HttpRetryOptions(attempts=1),  # لا إعادة محاولات داخلية - نتحكم بها نحن
    ),
)
GEMINI_SEM = asyncio.Semaphore(3)   # أقصى عدد طلبات متزامنة للنموذج
GEMINI_TOTAL_CAP = 100              # مهلة إجمالية للسؤال الواحد (ثانية)
QUEUE_WAIT_SECONDS = 15             # أقصى انتظار بالطابور قبل الاعتذار (بدل تعليق مفتوح)
RATE_LIMIT_COOLDOWN = 60            # تهدئة النموذج بعد 429 (حد طلبات)
BUSY_COOLDOWN = 30                  # تهدئة النموذج بعد 503/5xx (ضغط على مزوّد الخدمة)
# تهدئة لكل نموذج على حدة: النموذج المزدحم عند المزوّد يُتخطى مؤقتًا بدل ما يستهلك
# محاولات كل طالب، بينما يكمل النموذج الآخر القوي يخدمهم. تُرفع التهدئة تلقائيًا.
_model_cooldown: dict[str, float] = {}

# كاش شروحات الكويزات: سؤال الكويز وجوابه ثابتان للجميع، فالشرح يتولّد مرة واحدة
# ويُخدَّم لكل الطلاب بعدها بدون استهلاك طلبات ذكاء. لا يحوي أي بيانات شخصية.
# تنبيه: الشرح المخزن نص مولّد بالنموذج وليس مراجعة بشرية - الموثّق هو حرف الإجابة
# من ملف المصدر فقط. المفتاح يشمل السؤال والخيارات والإجابة والصورة ورقم إصدار:
# أي تعديل على البنوك أو برومبت الشرح يستدعي رفع EXPLAIN_CACHE_VERSION درجة.
EXPLAIN_CACHE_VERSION = 1
EXPLAIN_CACHE_FILE = os.environ.get("EXPLAIN_CACHE_FILE", "explain_cache.json")
EXPLAIN_CACHE_MAX = 500
explain_cache: dict[str, str] = {}

# ذاكرة منفصلة لكل شخص داخل كل محادثة: المفتاح "chat_id:user_id".
# تُحفظ في ملف memory.json - ملاحظة: على Render المجاني الذاكرة ترجع صفر عند إعادة النشر.
MEMORY_FILE = os.environ.get("MEMORY_FILE", "memory.json")
MAX_USERS = 300

histories: dict[str, deque] = defaultdict(lambda: deque(maxlen=MAX_HISTORY))
last_reply: dict[str, float] = defaultdict(float)
lock = asyncio.Lock()
_save_counter = 0


def load_explain_cache():
    try:
        with open(EXPLAIN_CACHE_FILE, encoding="utf-8") as fh:
            explain_cache.update(_json.load(fh))
        log.info("explain cache loaded: %s entries", len(explain_cache))
    except FileNotFoundError:
        pass
    except Exception as e:
        log.warning("explain cache load failed: %s", str(e)[:120])


def save_explain_cache():
    try:
        while len(explain_cache) > EXPLAIN_CACHE_MAX:
            explain_cache.pop(next(iter(explain_cache)))
        with open(EXPLAIN_CACHE_FILE, "w", encoding="utf-8") as fh:
            _json.dump(explain_cache, fh, ensure_ascii=False)
    except Exception as e:
        log.warning("explain cache save failed: %s", str(e)[:120])


def load_memory():
    try:
        with open(MEMORY_FILE, encoding="utf-8") as fh:
            data = _json.load(fh)
        for key, pairs in data.items():
            dq = histories[key]
            for u, b in pairs[-MAX_HISTORY:]:
                dq.append(types.Content(role="user", parts=[types.Part(text=u)]))
                dq.append(types.Content(role="model", parts=[types.Part(text=b)]))
        log.info("memory loaded: %s users", len(data))
    except FileNotFoundError:
        pass
    except Exception as e:
        log.warning("memory load failed: %s", str(e)[:120])


def save_memory():
    global _save_counter
    _save_counter += 1
    if _save_counter % 5:
        return
    try:
        while len(histories) > MAX_USERS:
            histories.pop(next(iter(histories)))
        data = {}
        for key, dq in histories.items():
            pairs, u = [], None
            for c in dq:
                txt = c.parts[0].text if c.parts else ""
                if c.role == "user":
                    u = txt
                elif u is not None:
                    pairs.append((u, txt))
                    u = None
            if pairs:
                data[key] = pairs
        with open(MEMORY_FILE, "w", encoding="utf-8") as fh:
            _json.dump(data, fh, ensure_ascii=False)
    except Exception as e:
        log.warning("memory save failed: %s", str(e)[:120])


def is_allowed_chat(msg) -> bool:
    """القروبات المسموحة: بس قروب المدقق (ALLOWED_CHAT_ID).
    لو فاضي = الكل مسموح (وضع الإعداد). الخاص مفتوح للكل -
    فحص العضوية في القناة والقروب يصير قبل الرد."""
    chat = msg.chat
    if chat.type == ChatType.PRIVATE:
        return True
    if ALLOWED_CHAT_ID:
        return str(chat.id) == ALLOWED_CHAT_ID
    return True


def not_owner_prompt() -> str:
    return (
        "هلا! أنا بوت قروب المدقق وأرد داخل القروب بس 🙏\n"
        "تعال اسألني هناك: " + GROUP_INVITE_LINK
    )


def should_respond(update: Update) -> bool:
    msg = update.message
    if not msg or not msg.text:
        return False
    chat = msg.chat
    if chat.type == ChatType.PRIVATE:
        return True
    text = msg.text.lower()
    # منشن مباشر للبوت
    if f"@{BOT_USERNAME}" in text:
        return True
    # رد على رسالة البوت
    if msg.reply_to_message and msg.reply_to_message.from_user and \
            msg.reply_to_message.from_user.username and \
            msg.reply_to_message.from_user.username.lower() == BOT_USERNAME:
        return True
    # اختياري: أي سؤال ينتهي بعلامة استفهام
    if RESPOND_TO_QUESTIONS and msg.text.strip().endswith(("؟", "?")):
        return True
    return False


class GeminiAllFailed(Exception):
    """كل النماذج فشلت - يحمل نوع الفشل (quota/busy/timeout/auth/other) للرسالة المناسبة."""
    def __init__(self, cls, err):
        super().__init__(str(err)[:200])
        self.cls = cls


def classify_gemini_error(e) -> str:
    """تصنيف خطأ Gemini: rate_limit (429) أو busy (5xx) أو timeout أو auth أو غيره."""
    if isinstance(e, genai_errors.APIError):
        code = getattr(e, "code", None)
        if code == 429:
            return "rate_limit"
        if code in (500, 502, 503, 504):
            return "busy"
        if code in (401, 403):
            return "auth"
        if code == 404:
            return "model_missing"
        return "api"
    if isinstance(e, TimeoutError):
        return "timeout"
    s = str(e).lower()
    if "timeout" in s or "timed out" in s or "deadline" in s:
        return "timeout"
    return "other"


def _gen_call(contents, system_instruction, temperature, max_tokens, models):
    last_err, last_cls = None, "busy"
    for model in models:
        if time.time() < _model_cooldown.get(model, 0):
            log.info("gemini skip model=%s (cooldown)", model)
            continue
        for attempt in range(2):  # محاولة ثانية سريعة فقط لو السبب ضغط/حصة
            t0 = time.time()
            try:
                resp = genai_client.models.generate_content(
                    model=model,
                    contents=contents,
                    config=types.GenerateContentConfig(
                        system_instruction=system_instruction,
                        temperature=temperature,
                        max_output_tokens=max_tokens,
                    ),
                )
                log.info("gemini ok model=%s attempt=%s %.1fs", model, attempt + 1, time.time() - t0)
                return resp
            except Exception as e:
                cls = classify_gemini_error(e)
                last_err, last_cls = e, cls
                log.warning(
                    "gemini fail class=%s model=%s attempt=%s %.1fs: %s",
                    cls, model, attempt + 1, time.time() - t0, str(e)[:150],
                )
                if cls in ("rate_limit", "busy") and attempt == 0:
                    time.sleep(1.0)
                    continue
                break  # أخطاء ثانية (مفتاح/نموذج مفقود/غيره): جرّب النموذج التالي فورًا
        if last_cls == "rate_limit":
            _model_cooldown[model] = time.time() + RATE_LIMIT_COOLDOWN
        elif last_cls == "busy":
            _model_cooldown[model] = time.time() + BUSY_COOLDOWN
    raise GeminiAllFailed(last_cls, last_err)


async def _generate(contents, system_instruction, temperature=0.7, max_tokens=2048,
                    models=None, total_cap=None):
    try:
        await asyncio.wait_for(GEMINI_SEM.acquire(), timeout=QUEUE_WAIT_SECONDS)
    except asyncio.TimeoutError:
        raise GeminiAllFailed("busy", "queue full")
    try:
        return await asyncio.wait_for(
            asyncio.to_thread(_gen_call, contents, system_instruction, temperature, max_tokens,
                              models or CHAT_MODELS),
            timeout=total_cap or GEMINI_TOTAL_CAP)
    finally:
        GEMINI_SEM.release()


# ردود واضحة حسب سبب الفشل
FAIL_REPLIES = {
    "rate_limit": "الطلبات كثيرة على خدمة الذكاء الحين 😅 جرب تسألني بعد دقيقة أو دقيقتين.",
    "busy": "الخدمة ضاغطة الحين 😅 جرب تسألني بعد دقيقة.",
    "timeout": "الخدمة بطيئة الحين وما ردت بوقتها 😅 جرب تسألني بعد دقيقة.",
    "auth": "فيه خلل بإعداداتي الحين، بيتحل قريب 🙏",
    "model_missing": "فيه خلل بإعداداتي الحين، بيتحل قريب 🙏",
    "api": "ما قدرت أرد الحين 😅 جرب بعد شوي.",
    "other": "ما قدرت أرد الحين 😅 جرب بعد شوي.",
}


async def ask_gemini(user_key: str, user_text: str) -> str:
    history = histories[user_key]
    contents = list(history) + [types.Content(role="user", parts=[types.Part(text=user_text)])]
    system_instruction = build_system_instruction()
    try:
        resp = await _generate(contents, system_instruction, models=CHAT_MODELS, total_cap=60)
    except asyncio.TimeoutError:
        log.warning("gemini total timeout (%s)", user_key)
        return FAIL_REPLIES["timeout"]
    except GeminiAllFailed as e:
        log.warning("gemini all models failed class=%s (%s)", e.cls, user_key)
        return FAIL_REPLIES.get(e.cls, FAIL_REPLIES["other"])
    answer = (resp.text or "").strip()
    try:
        fr = resp.candidates[0].finish_reason
        if str(fr).endswith("MAX_TOKENS") or "MAX_TOKENS" in str(fr):
            log.warning("answer truncated by model (MAX_TOKENS)")
            answer = tidy_cut(answer)
    except Exception:
        pass
    answer = clean_answer(answer)
    if not answer:
        answer = "ما قدرت أطلع إجابة واضحة، جرّب تعيد السؤال بصيغة ثانية."
    history.append(types.Content(role="user", parts=[types.Part(text=user_text)]))
    history.append(types.Content(role="model", parts=[types.Part(text=answer)]))
    save_memory()
    return answer


def is_quiz_request(text: str) -> bool:
    return "كويز" in text or "اختبرني" in text


QUIZ_TYPES = {"لفظي": "verbal", "كمي": "quantitative", "تحصيلي": "tahsili", "ستيب": "step"}
QUIZ_NAMES = {"verbal": "اللفظي", "quantitative": "الكمي", "tahsili": "التحصيلي", "step": "الستيب"}


async def send_quiz(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """كويز بصيغة استفتاء حقيقي (أزرار إجابة ويعرف الصح من الغلط فورًا).
    اللفظي جاهز؛ الكمي والتحصيلي والستيب تنضاف بنوكهم لما توصل ملفاتهم.
    سؤال فيه حقل "image" اختياري: رابط https أو مسار ملف داخل الريبو -
    يُرسل كصورة قبل الاستفتاء (لأسئلة الأشكال والرسومات في الكمي والتحصيلي)."""
    msg = update.message
    text = msg.text
    qtype = None
    for kw, key in QUIZ_TYPES.items():
        if kw in text:
            qtype = key
            break
    if qtype is None and "step" in text.lower():
        qtype = "step"
    if qtype is None:
        await msg.reply_text("حدد نوع الكويز: كويز لفظي / كمي / تحصيلي / ستيب 🙏")
        return
    bank = QUESTION_BANK.get(qtype) or []
    if not bank:
        await msg.reply_text(f"أسئلة كويز {QUIZ_NAMES[qtype]} ما وصلت بعد، بتنضاف قريب إن شاء الله 🙏")
        return
    import random as _rand
    q = _rand.choice(bank)
    image = q.get("image")
    if image:
        try:
            if str(image).startswith(("http://", "https://")):
                await context.bot.send_photo(chat_id=msg.chat_id, photo=image)
            else:
                ipath = os.path.join(os.path.dirname(os.path.abspath(__file__)), image)
                with open(ipath, "rb") as fh:
                    await context.bot.send_photo(chat_id=msg.chat_id, photo=fh)
        except Exception as e:
            log.warning("quiz image failed (%s): %s", image, str(e)[:120])
    await context.bot.send_poll(
        chat_id=msg.chat_id,
        question="السؤال في الصورة ☝️" if image else q["q"],
        options=q["options"],
        type=PollType.QUIZ,
        correct_option_id=q["correct"],
        explanation=q.get("why") or None,
        is_anonymous=False,
    )
    LAST_QUIZ[msg.chat_id] = {
        "q": q["q"], "options": q["options"], "correct": q["correct"],
        "image": image if image and not str(image).startswith(("http://", "https://")) else None,
        "qtype": qtype, "ts": time.time(),
    }
    await context.bot.send_message(
        chat_id=msg.chat_id,
        text="تبي شرح الإجابة؟ رد على الاستفتاء بكلمة «اشرح» ✍️",
    )


LAST_QUIZ: dict[int, dict] = {}
EXPLAIN_TTL = 900  # الشرح متاح ١٥ دقيقة بعد آخر كويز
EXPLAIN_WORDS = ("اشرح", "شرح", "ليش", "جاوب", "الجواب", "فهمني", "وش الجواب", "وش الاجابة", "وضح")


def is_explain_request(text: str) -> bool:
    t = text.replace(f"@{BOT_USERNAME}", "").strip().rstrip("؟?!.")
    return any(t == w or t.startswith(w + " ") for w in EXPLAIN_WORDS)


async def explain_quiz(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """شرح آخر كويز في المحادثة - النص أو الصورة مع النص (لأسئلة الأشكال الكمية)."""
    msg = update.message
    quiz = LAST_QUIZ.get(msg.chat_id)
    if not quiz or time.time() - quiz["ts"] > EXPLAIN_TTL:
        await msg.reply_text("ما فيه كويز قريب أشرحه - اطلب كويز جديد وبعدها قل «اشرح» 🙏")
        return
    letters = "أبجد"
    ci = quiz["correct"]
    opts = quiz["options"]
    opts_text = "\n".join(f"{letters[i]}) {o}" for i, o in enumerate(opts))
    if quiz.get("image"):
        q_text = "السؤال في الصورة المرفقة (سؤال كمي فيه شكل أو رسم)."
    else:
        q_text = quiz["q"]
    prompt = (
        "أنت مدرس قدرات/تحصيلي متمكن، خصوصًا في الرياضيات. اشرح للطالب حل هذا السؤال "
        "خطوة بخطوة باختصار (أقل من ١٢٠ كلمة)، بلغة واضحة، وبيّن ليش الإجابة "
        f"({letters[ci]}) هي الصحيحة، ولماذا الخيارات الأخرى خطأ بجملة واحدة إن أمكن.\n\n"
        f"السؤال: {q_text}\nالخيارات:\n{opts_text}\nالإجابة الصحيحة: ({letters[ci]}) {opts[ci]}"
    )
    parts = [types.Part(text=prompt)]
    if quiz.get("image"):
        try:
            ipath = os.path.join(os.path.dirname(os.path.abspath(__file__)), quiz["image"])
            with open(ipath, "rb") as fh:
                parts.append(types.Part.from_bytes(data=fh.read(), mime_type="image/jpeg"))
        except Exception as e:
            log.warning("explain image failed (%s): %s", quiz["image"], str(e)[:120])
    cache_key = hashlib.sha1(
        ("v" + str(EXPLAIN_CACHE_VERSION) + "|" + quiz["qtype"] + "|" + quiz["q"]
         + "|" + "|".join(opts) + "|" + str(ci) + "|" + str(quiz.get("image") or "")).encode("utf-8")
    ).hexdigest()
    cached = explain_cache.get(cache_key)
    if cached:
        await msg.reply_text(f"الإجابة الصحيحة: ({letters[ci]}) {opts[ci]}\n\n{cached}")
        return
    contents = [types.Content(role="user", parts=parts)]
    try:
        await context.bot.send_chat_action(chat_id=msg.chat_id, action="typing")
        resp = await _generate(contents, build_system_instruction(), temperature=0.3,
                               max_tokens=1500, models=SMART_MODELS, total_cap=GEMINI_TOTAL_CAP)
        answer = clean_answer((resp.text or "").strip())
        if not answer:
            raise ValueError("empty explanation")
        explain_cache[cache_key] = answer
        save_explain_cache()
        await msg.reply_text(f"الإجابة الصحيحة: ({letters[ci]}) {opts[ci]}\n\n{answer}")
    except asyncio.TimeoutError:
        log.warning("explain timeout")
        await msg.reply_text(
            f"الإجابة الصحيحة: ({letters[ci]}) {opts[ci]}\n"
            "الخدمة بطيئة الحين 😅 قل «اشرح» مرة ثانية بعد دقيقة."
        )
    except GeminiAllFailed as e:
        log.warning("explain failed class=%s: %s", e.cls, str(e)[:120])
        note = ("الطلبات كثيرة على خدمة الذكاء الحين 😅 قل «اشرح» مرة ثانية بعد دقيقتين."
                if e.cls == "rate_limit" else
                "ضغط على الشرح الحين 😅 قل «اشرح» مرة ثانية بعد دقيقة.")
        await msg.reply_text(f"الإجابة الصحيحة: ({letters[ci]}) {opts[ci]}\n{note}")
    except Exception as e:
        log.warning("explain failed: %s", str(e)[:150])
        await msg.reply_text(
            f"الإجابة الصحيحة: ({letters[ci]}) {opts[ci]}\n"
            "ضغط على الشرح الحين 😅 قل «اشرح» مرة ثانية بعد دقيقة."
        )


async def on_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    if not msg:
        return

    # قفل البوت: قروب غير مسموح -> ودّع واطلع منه.
    if not is_allowed_chat(msg):
        try:
            await msg.reply_text("هذا البوت خاص بقروب المدقق بس، بتطلع من هنا 👋")
        except Exception:
            pass
        try:
            await context.bot.leave_chat(msg.chat_id)
            log.info("left unauthorized chat %s", msg.chat_id)
        except Exception as e:
            log.warning("couldn't leave chat %s: %s", msg.chat_id, e)
        return

    if not should_respond(update):
        return
    chat_id = msg.chat_id

    # الخاص: لصاحب القناة بس. غيره نوجهه لقروب المدقق.
    if msg.chat.type == ChatType.PRIVATE:
        uid = msg.from_user.id if msg.from_user else 0
        if not (OWNER_USER_ID and str(uid) == OWNER_USER_ID):
            await msg.reply_text(not_owner_prompt())
            return

    # طلبات الكويز لها مسارها الخاص - ما تمر على النموذج
    if is_quiz_request(msg.text):
        await send_quiz(update, context)
        return

    # شرح آخر كويز (لكل الأنواع: لفظي/كمي/تحصيلي/ستيب)
    if is_explain_request(msg.text):
        await explain_quiz(update, context)
        return

    # كل شخص له محادثة وذاكرة مستقلة، ونعرّف النموذج باسم المتكلم
    uid = msg.from_user.id if msg.from_user else 0
    name = (msg.from_user.first_name or "يا صديقي") if msg.from_user else "يا صديقي"
    user_key = f"{chat_id}:{uid}"

    async with lock:
        now = asyncio.get_event_loop().time()
        if now - last_reply[user_key] < COOLDOWN_SECONDS:
            return
        last_reply[user_key] = now

    log.info("incoming from %s (%s): %s", chat_id, name, msg.text[:60])
    user_text = msg.text.replace(f"@{BOT_USERNAME}", "").strip()
    if not user_text:
        user_text = "سلّم عليهم وعرّفهم بنفسك بجملة وحدة."
    user_text = f"[{name}] {user_text}"

    try:
        await context.bot.send_chat_action(chat_id=chat_id, action="typing")
        answer = await ask_gemini(user_key, user_text)
        await msg.reply_text(answer)
        log.info("replied to chat %s", chat_id)
    except Exception as e:
        log.exception("Gemini/Telegram error: %s", e)
        await msg.reply_text("ضغط عليّ شوي الحين 😅 جرب تسألني بعد دقيقة.")


async def on_added_to_group(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """لو أحد ضاف البوت لقروب غير قروب المدقق، يطلع فورًا حتى لو ما أحد كتب شي."""
    msg = update.message
    if not msg or not ALLOWED_CHAT_ID:
        return
    if str(msg.chat_id) == ALLOWED_CHAT_ID:
        return
    try:
        await context.bot.leave_chat(msg.chat_id)
        log.info("left unauthorized group %s on join", msg.chat_id)
    except Exception as e:
        log.warning("couldn't leave group %s: %s", msg.chat_id, e)


async def on_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.message
    if not msg:
        return
    # قروب غير مسموح -> ما يرد (بيطلع منه عند أول رسالة عادية)
    if not is_allowed_chat(msg):
        return
    # الخاص: لصاحب القناة بس. غيره نوجهه لقروب المدقق.
    if msg.chat.type == ChatType.PRIVATE:
        uid = msg.from_user.id if msg.from_user else 0
        if not (OWNER_USER_ID and str(uid) == OWNER_USER_ID):
            await msg.reply_text(not_owner_prompt())
            return
    await msg.reply_text(
        "هلا! أنا المدقق 🤖\n"
        "أجاوب على أسئلتكم عن القدرات والتحصيلي وستيب والقبول الجامعي،\n"
        "وأرشح لكم أفضل مصدر حسب احتياجكم من تقييمات القناة.\n"
        "في القروب: اكتب سؤالك ومنشّني @" + BOT_USERNAME + " أو رد على رسالتي."
    )


async def on_id(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """يعطيك معرف المحادثة ومعرفك الشخصي - عشان تعبي متغيرات Render."""
    msg = update.message
    user_id = msg.from_user.id if msg.from_user else "؟"
    await msg.reply_text(
        f"معرف هذه المحادثة (chat id): {msg.chat_id}\n"
        f"معرفك الشخصي (user id): {user_id}"
    )


async def log_everything(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global LAST_UPDATE_TS
    LAST_UPDATE_TS = time.time()
    m = update.message or update.channel_post or update.edited_message
    if m:
        kind = "message" if update.message else ("channel_post" if update.channel_post else "edited")
        log.info("SAW %s chat=%s type=%s text=%s", kind, m.chat_id, m.chat.type, (m.text or "")[:60])
    else:
        log.info("SAW non-message update: %s", list(update.to_dict().keys()))


LAST_UPDATE_TS = time.time()   # آخر تحديث وصل من تيليجرام - لفحص التعليق من برّا


def start_health_server():
    """خادم ويب صغير عشان الاستضافة المجانية تعرف أن البوت حي (Render يتطلب منفذ مفتوح).
    يرد بعمر آخر تحديث: رقم كبير + المحادثة نشطة = البولينق معلق."""
    import threading
    from http.server import BaseHTTPRequestHandler, HTTPServer

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            ago = int(time.time() - LAST_UPDATE_TS)
            self.send_response(200)
            self.end_headers()
            self.wfile.write(f"bot is alive, last update {ago}s ago".encode())

        def log_message(self, *args):
            pass

    port = int(os.environ.get("PORT", "8080"))
    server = HTTPServer(("0.0.0.0", port), Handler)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    log.info("health server listening on port %s", port)


def ensure_kami_images():
    """يفك ضغط kami.zip إلى مجلد kami/ إذا كان المجلد مفقودًا (يحصل لما يُرفع الملف مضغوطًا للريبو).
    يتعامل مع zip فيه مجلد kami/ داخلي أو ملفات مباشرة، ويتجاهل المسارات غير الآمنة،
    ولا يوقف البوت أبدًا - يسجل النتيجة في السجل فقط."""
    base = os.path.dirname(os.path.abspath(__file__))
    kami_dir = os.path.join(base, "kami")
    try:
        if os.path.isdir(kami_dir) and any(n.lower().endswith(".jpg") for n in os.listdir(kami_dir)):
            return  # الصور موجودة أصلاً
        zip_path = os.path.join(base, "kami.zip")
        if not os.path.isfile(zip_path):
            log.warning("kami images missing: no kami/ folder and no kami.zip next to bot.py")
            return
        import zipfile
        os.makedirs(kami_dir, exist_ok=True)
        count = 0
        with zipfile.ZipFile(zip_path) as zf:
            for info in zf.infolist():
                if info.is_dir():
                    continue
                parts = [p for p in info.filename.replace("\\", "/").split("/") if p not in ("", ".")]
                if parts and parts[0].lower() == "kami":
                    parts = parts[1:]  # zip فيه مجلد kami/ داخلي
                if len(parts) != 1 or not parts[0].lower().endswith((".jpg", ".jpeg", ".png")):
                    continue  # مسار غير آمن أو ملف مو صورة: نتجاهله
                with zf.open(info) as fsrc, open(os.path.join(kami_dir, parts[0]), "wb") as fdst:
                    fdst.write(fsrc.read())
                count += 1
        log.info("kami.zip extracted: %s images into kami/", count)
    except Exception as e:
        log.warning("kami.zip extract failed (bot continues): %s", str(e)[:150])


def main():
    ensure_kami_images()
    load_explain_cache()
    load_memory()
    log.info("models chat=%s smart=%s", CHAT_MODELS, SMART_MODELS)
    start_health_server()
    app = Application.builder().token(TELEGRAM_BOT_TOKEN).build()
    app.add_handler(MessageHandler(filters.ALL, log_everything), group=-1)
    app.add_handler(CommandHandler("start", on_start))
    app.add_handler(CommandHandler("id", on_id))
    app.add_handler(MessageHandler(filters.StatusUpdate.NEW_CHAT_MEMBERS, on_added_to_group))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, on_message))
    log.info(
        "Bot is running (polling)... lock: %s",
        f"group {ALLOWED_CHAT_ID}" if ALLOWED_CHAT_ID else "OPEN (setup mode)",
    )
    app.run_polling(allowed_updates=["message", "channel_post", "edited_message"], drop_pending_updates=True)


if __name__ == "__main__":
    main()
